    const a = this.items
    a.push(value)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1
      if (this.compare(a[i], a[p]) >= 0) break
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
