function lastStoneWeight(stones) {
  const heap = new MinHeap((a, b) => b - a)
  for (const s of stones) heap.push(s)
  while (heap.size > 1) {
    const y = heap.pop()
    const x = heap.pop()
    if (y !== x) heap.push(y - x)
  }
  return heap.size ? heap.pop() : 0
}

