import heapq

def k_closest(points, k):
    heap = []  # max-heap by distance, stored as (-distance, x, y)
    for x, y in points:
        heapq.heappush(heap, (-(x * x + y * y), x, y))
        if len(heap) > k:
            heapq.heappop(heap)
    return [[x, y] for _, x, y in heap]

