function mergeKSortedArrays(arrays) {
  const heap = new MinHeap((a, b) => a[0] - b[0])
  arrays.forEach((arr, i) => {
    if (arr.length) heap.push([arr[0], i, 0])
  })
  const out = []
  while (heap.size) {
    const [val, i, j] = heap.pop()
    out.push(val)
    if (j + 1 < arrays[i].length) heap.push([arrays[i][j + 1], i, j + 1])
  }
  return out
}
